import{at as e,it as t,n,vt as r}from"./chunks/framework.BUQROvXk.js";var i=JSON.parse(`{"title":"Class: Brain","description":"","frontmatter":{},"headers":[],"relativePath":"api/@jsprismarine/entity-brains/classes/Brain.md","filePath":"api/@jsprismarine/entity-brains/classes/Brain.md"}`),a={name:`api/@jsprismarine/entity-brains/classes/Brain.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<p><a href="./../../../">JSPrismarine</a> / <a href="./../">@jsprismarine/entity-brains</a> / Brain</p><h1 id="class-brain" tabindex="-1">Class: Brain <a class="header-anchor" href="#class-brain" aria-label="Permalink to “Class: Brain”">​</a></h1><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/f0e5d5ec4cc03a06dd45fbbaabbccaee04a20bf4/packages/entity-brains/src/brain.ts#L120" target="_blank" rel="noreferrer">brain.ts:120</a></p><p>One mob&#39;s memories, sensors and activity table. Java&#39;s <code>Brain</code>.</p><p>A tick runs every sensor, ages every memory slot, starts the stopped behaviors of the active activities in ascending priority order, then ticks the running ones. The brain never picks an activity itself; the mob&#39;s <code>updateActivity</code> does that, and the brain only reports whether an activity&#39;s conditions hold.</p><h2 id="constructors" tabindex="-1">Constructors <a class="header-anchor" href="#constructors" aria-label="Permalink to “Constructors”">​</a></h2><h3 id="constructor" tabindex="-1">Constructor <a class="header-anchor" href="#constructor" aria-label="Permalink to “Constructor”">​</a></h3><blockquote><p><strong>new Brain</strong>(<code>definition</code>): <code>Brain</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/f0e5d5ec4cc03a06dd45fbbaabbccaee04a20bf4/packages/entity-brains/src/brain.ts#L135" target="_blank" rel="noreferrer">brain.ts:135</a></p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="definition" tabindex="-1">definition <a class="header-anchor" href="#definition" aria-label="Permalink to “definition”">​</a></h5><p><a href="./../#braindefinition"><code>BrainDefinition</code></a></p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h4><p><code>Brain</code></p><h2 id="accessors" tabindex="-1">Accessors <a class="header-anchor" href="#accessors" aria-label="Permalink to “Accessors”">​</a></h2><h3 id="registeredmemories" tabindex="-1">registeredMemories <a class="header-anchor" href="#registeredmemories" aria-label="Permalink to “registeredMemories”">​</a></h3><h4 id="get-signature" tabindex="-1">Get Signature <a class="header-anchor" href="#get-signature" aria-label="Permalink to “Get Signature”">​</a></h4><blockquote><p><strong>get</strong> <strong>registeredMemories</strong>(): readonly <a href="./../#memorymoduletype"><code>MemoryModuleType</code></a>&lt;<code>unknown</code>&gt;[]</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/f0e5d5ec4cc03a06dd45fbbaabbccaee04a20bf4/packages/entity-brains/src/brain.ts#L283" target="_blank" rel="noreferrer">brain.ts:283</a></p><p>Every registered memory module type.</p><h5 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h5><p>readonly <a href="./../#memorymoduletype"><code>MemoryModuleType</code></a>&lt;<code>unknown</code>&gt;[]</p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="checkmemory" tabindex="-1">checkMemory() <a class="header-anchor" href="#checkmemory" aria-label="Permalink to “checkMemory()”">​</a></h3><blockquote><p><strong>checkMemory</strong>(<code>memory</code>, <code>status</code>): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/f0e5d5ec4cc03a06dd45fbbaabbccaee04a20bf4/packages/entity-brains/src/brain.ts#L212" target="_blank" rel="noreferrer">brain.ts:212</a></p><p>Java&#39;s <code>Brain.checkMemory</code>. An unregistered memory fails every status, including <code>registered</code>, which is what makes a brain ignore a behavior whose memories it never declared.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="memory" tabindex="-1">memory <a class="header-anchor" href="#memory" aria-label="Permalink to “memory”">​</a></h5><p><a href="./../#memorymoduletype"><code>MemoryModuleType</code></a>&lt;<code>unknown</code>&gt;</p><h5 id="status" tabindex="-1">status <a class="header-anchor" href="#status" aria-label="Permalink to “status”">​</a></h5><p><a href="./../#memorystatus"><code>MemoryStatus</code></a></p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><hr><h3 id="clearmemories" tabindex="-1">clearMemories() <a class="header-anchor" href="#clearmemories" aria-label="Permalink to “clearMemories()”">​</a></h3><blockquote><p><strong>clearMemories</strong>(): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/f0e5d5ec4cc03a06dd45fbbaabbccaee04a20bf4/packages/entity-brains/src/brain.ts#L276" target="_blank" rel="noreferrer">brain.ts:276</a></p><p>Empties every registered memory without unregistering any.</p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="delaysensorstarts" tabindex="-1">delaySensorStarts() <a class="header-anchor" href="#delaysensorstarts" aria-label="Permalink to “delaySensorStarts()”">​</a></h3><blockquote><p><strong>delaySensorStarts</strong>(<code>randomInt</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/f0e5d5ec4cc03a06dd45fbbaabbccaee04a20bf4/packages/entity-brains/src/brain.ts#L156" target="_blank" rel="noreferrer">brain.ts:156</a></p><p>Randomizes each sensor&#39;s first scan tick, as Java&#39;s <code>Sensor::randomlyDelayStart</code> does.</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="randomint" tabindex="-1">randomInt <a class="header-anchor" href="#randomint" aria-label="Permalink to “randomInt”">​</a></h5><p>(<code>bound</code>) =&gt; <code>number</code></p><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="erasememory" tabindex="-1">eraseMemory() <a class="header-anchor" href="#erasememory" aria-label="Permalink to “eraseMemory()”">​</a></h3><blockquote><p><strong>eraseMemory</strong>(<code>memory</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/f0e5d5ec4cc03a06dd45fbbaabbccaee04a20bf4/packages/entity-brains/src/brain.ts#L271" target="_blank" rel="noreferrer">brain.ts:271</a></p><p>Empties one memory slot, leaving it registered.</p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="memory-1" tabindex="-1">memory <a class="header-anchor" href="#memory-1" aria-label="Permalink to “memory”">​</a></h5><p><a href="./../#memorymoduletype"><code>MemoryModuleType</code></a>&lt;<code>unknown</code>&gt;</p><h4 id="returns-5" tabindex="-1">Returns <a class="header-anchor" href="#returns-5" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="getactiveactivities" tabindex="-1">getActiveActivities() <a class="header-anchor" href="#getactiveactivities" aria-label="Permalink to “getActiveActivities()”">​</a></h3><blockquote><p><strong>getActiveActivities</strong>(): readonly <a href="./../#activity"><code>Activity</code></a>[]</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/f0e5d5ec4cc03a06dd45fbbaabbccaee04a20bf4/packages/entity-brains/src/brain.ts#L308" target="_blank" rel="noreferrer">brain.ts:308</a></p><p>Every activity in force this tick, core ones included.</p><h4 id="returns-6" tabindex="-1">Returns <a class="header-anchor" href="#returns-6" aria-label="Permalink to “Returns”">​</a></h4><p>readonly <a href="./../#activity"><code>Activity</code></a>[]</p><hr><h3 id="getactivenoncoreactivity" tabindex="-1">getActiveNonCoreActivity() <a class="header-anchor" href="#getactivenoncoreactivity" aria-label="Permalink to “getActiveNonCoreActivity()”">​</a></h3><blockquote><p><strong>getActiveNonCoreActivity</strong>(): <a href="./../#activity"><code>Activity</code></a> | <code>undefined</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/f0e5d5ec4cc03a06dd45fbbaabbccaee04a20bf4/packages/entity-brains/src/brain.ts#L313" target="_blank" rel="noreferrer">brain.ts:313</a></p><p>The one non-core activity in force, which is what a mob&#39;s sound and pose logic reads.</p><h4 id="returns-7" tabindex="-1">Returns <a class="header-anchor" href="#returns-7" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./../#activity"><code>Activity</code></a> | <code>undefined</code></p><hr><h3 id="getmemory" tabindex="-1">getMemory() <a class="header-anchor" href="#getmemory" aria-label="Permalink to “getMemory()”">​</a></h3><blockquote><p><strong>getMemory</strong>&lt;<code>Value</code>&gt;(<code>memory</code>): <code>Value</code> | <code>undefined</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/f0e5d5ec4cc03a06dd45fbbaabbccaee04a20bf4/packages/entity-brains/src/brain.ts#L228" target="_blank" rel="noreferrer">brain.ts:228</a></p><p>The memory&#39;s value, or <code>undefined</code> when empty or unregistered.</p><h4 id="type-parameters" tabindex="-1">Type Parameters <a class="header-anchor" href="#type-parameters" aria-label="Permalink to “Type Parameters”">​</a></h4><h5 id="value" tabindex="-1">Value <a class="header-anchor" href="#value" aria-label="Permalink to “Value”">​</a></h5><p><code>Value</code></p><h4 id="parameters-4" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-4" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="memory-2" tabindex="-1">memory <a class="header-anchor" href="#memory-2" aria-label="Permalink to “memory”">​</a></h5><p><a href="./../#memorymoduletype"><code>MemoryModuleType</code></a>&lt;<code>Value</code>&gt;</p><h4 id="returns-8" tabindex="-1">Returns <a class="header-anchor" href="#returns-8" aria-label="Permalink to “Returns”">​</a></h4><p><code>Value</code> | <code>undefined</code></p><hr><h3 id="getrunningbehaviors" tabindex="-1">getRunningBehaviors() <a class="header-anchor" href="#getrunningbehaviors" aria-label="Permalink to “getRunningBehaviors()”">​</a></h3><blockquote><p><strong>getRunningBehaviors</strong>(): readonly <a href="./../#behaviorcontrol"><code>BehaviorControl</code></a>[]</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/f0e5d5ec4cc03a06dd45fbbaabbccaee04a20bf4/packages/entity-brains/src/brain.ts#L323" target="_blank" rel="noreferrer">brain.ts:323</a></p><p>Every running behavior, in ascending priority order. A debug read-out and the tests read this.</p><h4 id="returns-9" tabindex="-1">Returns <a class="header-anchor" href="#returns-9" aria-label="Permalink to “Returns”">​</a></h4><p>readonly <a href="./../#behaviorcontrol"><code>BehaviorControl</code></a>[]</p><hr><h3 id="gettimeuntilexpiry" tabindex="-1">getTimeUntilExpiry() <a class="header-anchor" href="#gettimeuntilexpiry" aria-label="Permalink to “getTimeUntilExpiry()”">​</a></h3><blockquote><p><strong>getTimeUntilExpiry</strong>(<code>memory</code>): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/f0e5d5ec4cc03a06dd45fbbaabbccaee04a20bf4/packages/entity-brains/src/brain.ts#L238" target="_blank" rel="noreferrer">brain.ts:238</a></p><p>Ticks remaining before the memory expires, or <a href="./MemorySlot.html#never-expire">MemorySlot.NEVER_EXPIRE</a>.</p><h4 id="parameters-5" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-5" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="memory-3" tabindex="-1">memory <a class="header-anchor" href="#memory-3" aria-label="Permalink to “memory”">​</a></h5><p><a href="./../#memorymoduletype"><code>MemoryModuleType</code></a>&lt;<code>unknown</code>&gt;</p><h4 id="returns-10" tabindex="-1">Returns <a class="header-anchor" href="#returns-10" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><hr><h3 id="hasmemoryvalue" tabindex="-1">hasMemoryValue() <a class="header-anchor" href="#hasmemoryvalue" aria-label="Permalink to “hasMemoryValue()”">​</a></h3><blockquote><p><strong>hasMemoryValue</strong>(<code>memory</code>): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/f0e5d5ec4cc03a06dd45fbbaabbccaee04a20bf4/packages/entity-brains/src/brain.ts#L204" target="_blank" rel="noreferrer">brain.ts:204</a></p><p>Whether the memory is registered and currently holds a value.</p><h4 id="parameters-6" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-6" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="memory-4" tabindex="-1">memory <a class="header-anchor" href="#memory-4" aria-label="Permalink to “memory”">​</a></h5><p><a href="./../#memorymoduletype"><code>MemoryModuleType</code></a>&lt;<code>unknown</code>&gt;</p><h4 id="returns-11" tabindex="-1">Returns <a class="header-anchor" href="#returns-11" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><hr><h3 id="isactive" tabindex="-1">isActive() <a class="header-anchor" href="#isactive" aria-label="Permalink to “isActive()”">​</a></h3><blockquote><p><strong>isActive</strong>(<code>activity</code>): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/f0e5d5ec4cc03a06dd45fbbaabbccaee04a20bf4/packages/entity-brains/src/brain.ts#L303" target="_blank" rel="noreferrer">brain.ts:303</a></p><p>Whether the activity is in force this tick, counting the core activities.</p><h4 id="parameters-7" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-7" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="activity" tabindex="-1">activity <a class="header-anchor" href="#activity" aria-label="Permalink to “activity”">​</a></h5><p><a href="./../#activity"><code>Activity</code></a></p><h4 id="returns-12" tabindex="-1">Returns <a class="header-anchor" href="#returns-12" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><hr><h3 id="ismemoryvalue" tabindex="-1">isMemoryValue() <a class="header-anchor" href="#ismemoryvalue" aria-label="Permalink to “isMemoryValue()”">​</a></h3><blockquote><p><strong>isMemoryValue</strong>&lt;<code>Value</code>&gt;(<code>memory</code>, <code>value</code>): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/f0e5d5ec4cc03a06dd45fbbaabbccaee04a20bf4/packages/entity-brains/src/brain.ts#L233" target="_blank" rel="noreferrer">brain.ts:233</a></p><p>Whether the memory holds exactly this value, Java&#39;s <code>Brain.isMemoryValue</code>.</p><h4 id="type-parameters-1" tabindex="-1">Type Parameters <a class="header-anchor" href="#type-parameters-1" aria-label="Permalink to “Type Parameters”">​</a></h4><h5 id="value-1" tabindex="-1">Value <a class="header-anchor" href="#value-1" aria-label="Permalink to “Value”">​</a></h5><p><code>Value</code></p><h4 id="parameters-8" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-8" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="memory-5" tabindex="-1">memory <a class="header-anchor" href="#memory-5" aria-label="Permalink to “memory”">​</a></h5><p><a href="./../#memorymoduletype"><code>MemoryModuleType</code></a>&lt;<code>Value</code>&gt;</p><h5 id="value-2" tabindex="-1">value <a class="header-anchor" href="#value-2" aria-label="Permalink to “value”">​</a></h5><p><code>Value</code></p><h4 id="returns-13" tabindex="-1">Returns <a class="header-anchor" href="#returns-13" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><hr><h3 id="setactiveactivityifpossible" tabindex="-1">setActiveActivityIfPossible() <a class="header-anchor" href="#setactiveactivityifpossible" aria-label="Permalink to “setActiveActivityIfPossible()”">​</a></h3><blockquote><p><strong>setActiveActivityIfPossible</strong>(<code>activity</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/f0e5d5ec4cc03a06dd45fbbaabbccaee04a20bf4/packages/entity-brains/src/brain.ts#L343" target="_blank" rel="noreferrer">brain.ts:343</a></p><p>Switches to the activity when its memory conditions hold, and to the default when not.</p><h4 id="parameters-9" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-9" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="activity-1" tabindex="-1">activity <a class="header-anchor" href="#activity-1" aria-label="Permalink to “activity”">​</a></h5><p><a href="./../#activity"><code>Activity</code></a></p><h4 id="returns-14" tabindex="-1">Returns <a class="header-anchor" href="#returns-14" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="setactiveactivitytofirstvalid" tabindex="-1">setActiveActivityToFirstValid() <a class="header-anchor" href="#setactiveactivitytofirstvalid" aria-label="Permalink to “setActiveActivityToFirstValid()”">​</a></h3><blockquote><p><strong>setActiveActivityToFirstValid</strong>(<code>activities</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/f0e5d5ec4cc03a06dd45fbbaabbccaee04a20bf4/packages/entity-brains/src/brain.ts#L356" target="_blank" rel="noreferrer">brain.ts:356</a></p><p>Switches to the first activity in the list whose conditions hold, and leaves the current one alone when none do. This is what every mob&#39;s <code>updateActivity</code> calls, and the list order is the mob&#39;s priority order between activities.</p><h4 id="parameters-10" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-10" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="activities" tabindex="-1">activities <a class="header-anchor" href="#activities" aria-label="Permalink to “activities”">​</a></h5><p>readonly <a href="./../#activity"><code>Activity</code></a>[]</p><h4 id="returns-15" tabindex="-1">Returns <a class="header-anchor" href="#returns-15" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="setcoreactivities" tabindex="-1">setCoreActivities() <a class="header-anchor" href="#setcoreactivities" aria-label="Permalink to “setCoreActivities()”">​</a></h3><blockquote><p><strong>setCoreActivities</strong>(<code>activities</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/f0e5d5ec4cc03a06dd45fbbaabbccaee04a20bf4/packages/entity-brains/src/brain.ts#L293" target="_blank" rel="noreferrer">brain.ts:293</a></p><p>Replaces the activities that stay active alongside whichever one is in force.</p><h4 id="parameters-11" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-11" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="activities-1" tabindex="-1">activities <a class="header-anchor" href="#activities-1" aria-label="Permalink to “activities”">​</a></h5><p>readonly <a href="./../#activity"><code>Activity</code></a>[]</p><h4 id="returns-16" tabindex="-1">Returns <a class="header-anchor" href="#returns-16" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="setdefaultactivity" tabindex="-1">setDefaultActivity() <a class="header-anchor" href="#setdefaultactivity" aria-label="Permalink to “setDefaultActivity()”">​</a></h3><blockquote><p><strong>setDefaultActivity</strong>(<code>activity</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/f0e5d5ec4cc03a06dd45fbbaabbccaee04a20bf4/packages/entity-brains/src/brain.ts#L298" target="_blank" rel="noreferrer">brain.ts:298</a></p><p>Replaces the activity the brain falls back to when no other one&#39;s conditions hold.</p><h4 id="parameters-12" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-12" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="activity-2" tabindex="-1">activity <a class="header-anchor" href="#activity-2" aria-label="Permalink to “activity”">​</a></h5><p><a href="./../#activity"><code>Activity</code></a></p><h4 id="returns-17" tabindex="-1">Returns <a class="header-anchor" href="#returns-17" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="setmemory" tabindex="-1">setMemory() <a class="header-anchor" href="#setmemory" aria-label="Permalink to “setMemory()”">​</a></h3><blockquote><p><strong>setMemory</strong>&lt;<code>Value</code>&gt;(<code>memory</code>, <code>value</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/f0e5d5ec4cc03a06dd45fbbaabbccaee04a20bf4/packages/entity-brains/src/brain.ts#L249" target="_blank" rel="noreferrer">brain.ts:249</a></p><p>Writes a memory. <code>undefined</code> erases it, and so does an empty array: Java&#39;s <code>isEmptyCollection</code> check means a sensor that finds nothing clears the memory rather than storing an empty list, which is what lets <code>value_present</code> mean &quot;found something&quot;.</p><p>Writing an unregistered memory is silently dropped, as Java&#39;s null-slot check is.</p><h4 id="type-parameters-2" tabindex="-1">Type Parameters <a class="header-anchor" href="#type-parameters-2" aria-label="Permalink to “Type Parameters”">​</a></h4><h5 id="value-3" tabindex="-1">Value <a class="header-anchor" href="#value-3" aria-label="Permalink to “Value”">​</a></h5><p><code>Value</code></p><h4 id="parameters-13" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-13" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="memory-6" tabindex="-1">memory <a class="header-anchor" href="#memory-6" aria-label="Permalink to “memory”">​</a></h5><p><a href="./../#memorymoduletype"><code>MemoryModuleType</code></a>&lt;<code>Value</code>&gt;</p><h5 id="value-4" tabindex="-1">value <a class="header-anchor" href="#value-4" aria-label="Permalink to “value”">​</a></h5><p><code>Value</code> | <code>undefined</code></p><h4 id="returns-18" tabindex="-1">Returns <a class="header-anchor" href="#returns-18" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="setmemorywithexpiry" tabindex="-1">setMemoryWithExpiry() <a class="header-anchor" href="#setmemorywithexpiry" aria-label="Permalink to “setMemoryWithExpiry()”">​</a></h3><blockquote><p><strong>setMemoryWithExpiry</strong>&lt;<code>Value</code>&gt;(<code>memory</code>, <code>value</code>, <code>timeToLive</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/f0e5d5ec4cc03a06dd45fbbaabbccaee04a20bf4/packages/entity-brains/src/brain.ts#L254" target="_blank" rel="noreferrer">brain.ts:254</a></p><p>Writes a memory that erases itself after <code>timeToLive</code> brain ticks.</p><h4 id="type-parameters-3" tabindex="-1">Type Parameters <a class="header-anchor" href="#type-parameters-3" aria-label="Permalink to “Type Parameters”">​</a></h4><h5 id="value-5" tabindex="-1">Value <a class="header-anchor" href="#value-5" aria-label="Permalink to “Value”">​</a></h5><p><code>Value</code></p><h4 id="parameters-14" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-14" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="memory-7" tabindex="-1">memory <a class="header-anchor" href="#memory-7" aria-label="Permalink to “memory”">​</a></h5><p><a href="./../#memorymoduletype"><code>MemoryModuleType</code></a>&lt;<code>Value</code>&gt;</p><h5 id="value-6" tabindex="-1">value <a class="header-anchor" href="#value-6" aria-label="Permalink to “value”">​</a></h5><p><code>Value</code> | <code>undefined</code></p><h5 id="timetolive" tabindex="-1">timeToLive <a class="header-anchor" href="#timetolive" aria-label="Permalink to “timeToLive”">​</a></h5><p><code>number</code></p><h4 id="returns-19" tabindex="-1">Returns <a class="header-anchor" href="#returns-19" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="setschedule" tabindex="-1">setSchedule() <a class="header-anchor" href="#setschedule" aria-label="Permalink to “setSchedule()”">​</a></h3><blockquote><p><strong>setSchedule</strong>(<code>schedule</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/f0e5d5ec4cc03a06dd45fbbaabbccaee04a20bf4/packages/entity-brains/src/brain.ts#L288" target="_blank" rel="noreferrer">brain.ts:288</a></p><p>Replaces the schedule <a href="#updateactivityfromschedule">Brain.updateActivityFromSchedule</a> reads. Only the villager has one.</p><h4 id="parameters-15" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-15" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="schedule" tabindex="-1">schedule <a class="header-anchor" href="#schedule" aria-label="Permalink to “schedule”">​</a></h5><p><a href="./../#schedule-1"><code>Schedule</code></a> | <code>undefined</code></p><h4 id="returns-20" tabindex="-1">Returns <a class="header-anchor" href="#returns-20" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="stopall" tabindex="-1">stopAll() <a class="header-anchor" href="#stopall" aria-label="Permalink to “stopAll()”">​</a></h3><blockquote><p><strong>stopAll</strong>(<code>context</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/f0e5d5ec4cc03a06dd45fbbaabbccaee04a20bf4/packages/entity-brains/src/brain.ts#L427" target="_blank" rel="noreferrer">brain.ts:427</a></p><p>Stops every running behavior, as Java does when a villager&#39;s brain is rebuilt.</p><h4 id="parameters-16" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-16" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="context" tabindex="-1">context <a class="header-anchor" href="#context" aria-label="Permalink to “context”">​</a></h5><p><a href="./../#braincontext"><code>BrainContext</code></a></p><h4 id="returns-21" tabindex="-1">Returns <a class="header-anchor" href="#returns-21" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="tick" tabindex="-1">tick() <a class="header-anchor" href="#tick" aria-label="Permalink to “tick()”">​</a></h3><blockquote><p><strong>tick</strong>(<code>context</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/f0e5d5ec4cc03a06dd45fbbaabbccaee04a20bf4/packages/entity-brains/src/brain.ts#L419" target="_blank" rel="noreferrer">brain.ts:419</a></p><p>One brain tick, in Java&#39;s order: age the memories, run the sensors, start every stopped behavior whose activity is active, then tick every running one.</p><p>Starting before ticking is observable: a behavior started this tick also ticks this tick.</p><h4 id="parameters-17" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-17" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="context-1" tabindex="-1">context <a class="header-anchor" href="#context-1" aria-label="Permalink to “context”">​</a></h5><p><a href="./../#braincontext"><code>BrainContext</code></a></p><h4 id="returns-22" tabindex="-1">Returns <a class="header-anchor" href="#returns-22" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="updateactivityfromschedule" tabindex="-1">updateActivityFromSchedule() <a class="header-anchor" href="#updateactivityfromschedule" aria-label="Permalink to “updateActivityFromSchedule()”">​</a></h3><blockquote><p><strong>updateActivityFromSchedule</strong>(<code>gameTime</code>, <code>dayTime</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/f0e5d5ec4cc03a06dd45fbbaabbccaee04a20bf4/packages/entity-brains/src/brain.ts#L402" target="_blank" rel="noreferrer">brain.ts:402</a></p><p>Reads the schedule and switches activity, at most once every twenty ticks.</p><p>The throttle is Java&#39;s and it is observable: a villager crossing a keyframe can take up to a second to notice.</p><h4 id="parameters-18" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-18" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="gametime" tabindex="-1">gameTime <a class="header-anchor" href="#gametime" aria-label="Permalink to “gameTime”">​</a></h5><p><code>number</code></p><h5 id="daytime" tabindex="-1">dayTime <a class="header-anchor" href="#daytime" aria-label="Permalink to “dayTime”">​</a></h5><p><code>number</code></p><h4 id="returns-23" tabindex="-1">Returns <a class="header-anchor" href="#returns-23" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="usedefaultactivity" tabindex="-1">useDefaultActivity() <a class="header-anchor" href="#usedefaultactivity" aria-label="Permalink to “useDefaultActivity()”">​</a></h3><blockquote><p><strong>useDefaultActivity</strong>(): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/f0e5d5ec4cc03a06dd45fbbaabbccaee04a20bf4/packages/entity-brains/src/brain.ts#L338" target="_blank" rel="noreferrer">brain.ts:338</a></p><p>Switches to the default activity without checking any conditions.</p><h4 id="returns-24" tabindex="-1">Returns <a class="header-anchor" href="#returns-24" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p>`,264)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};